import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.stream.*;


public class E {

    private static final FastReader IN = new FastReader();
    private static final FastWriter OUT = new FastWriter();

    public static void main(String[] args) {
        new E().run();
    }

    private void run() {
        int tests = 1;
        while (tests-- > 0) {
            solve();
        }
        OUT.flush();
    }

    private void solve() {
        int n = IN.nextInt();
        long kt = IN.nextLong();

        if (kt >= n) {
            OUT.println(0);
            return;
        }

        int k = (int) kt;
        int mod = 998244353;
        long[] facts = factorials(n, mod);

        long ans = 0;
        int c = n - k;
        for (int i = 0; i <= c; i++) {
            long term = multiply(comb(c, i, facts, mod), powMod(c - i, n, mod), mod);
            if ((i & 1) == 0) {
                ans = add(ans, term, mod);
            } else {
                ans = subtract(ans, term, mod);
            }
        }
        ans = multiply(ans, comb(n, n - k, facts, mod), mod);
        if (k > 0) ans = multiply(ans, 2, mod);
        OUT.println(ans);
    }

    private static long add(long a, long b, int mod) {
        long c = a + b;
        return c >= mod ? c - mod : c;
    }

    private static long subtract(long a, long b, int mod) {
        long c = a - b;
        return c < 0 ? c + mod : c;
    }

    private static long multiply(long a, long b, int mod) {
        return (a * b) % mod;
    }

    private static long powMod(long base, long exp, int mod) {
        long res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }

    private static long comb(int n, int k, long[] facts, int mod) {
        if (k < 0 || k > n) return 0;
        return multiply(facts[n], powMod(multiply(facts[k], facts[n - k], mod), mod - 2, mod), mod);
    }

    private static long[] factorials(int n, int mod) {
        long[] f = new long[n + 1];
        f[0] = 1;
        for (int i = 1; i <= n; i++) f[i] = (f[i - 1] * i) % mod;
        return f;
    }

}


class FastReader {

    private static final BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    private StringTokenizer st;

    public String next() {
        while (st == null || !st.hasMoreTokens()) {
            try {
                st = new StringTokenizer(br.readLine());
            } catch (IOException e) {
                return null;
            }
        }
        return st.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    public long nextLong() {
        return Long.parseLong(next());
    }

    public double nextDouble() {
        return Double.parseDouble(next());
    }

    public BigDecimal nextBigDecimal() {
        return new BigDecimal(next());
    }

    public BigInteger nextBigInteger() {
        return new BigInteger(next());
    }

    public boolean nextBoolean() {
        return Boolean.parseBoolean(next());
    }

    public byte nextByte() {
        return Byte.parseByte(next());
    }

    public int[] nextIntArray(int length) {
        int[] a = new int[length];
        for (int i = 0; i < length; i++) a[i] = nextInt();
        return a;
    }

    public long[] nextLongArray(int length) {
        long[] a = new long[length];
        for (int i = 0; i < length; i++) a[i] = nextLong();
        return a;
    }

    public double[] nextDoubleArray(int length) {
        double[] a = new double[length];
        for (int i = 0; i < length; i++) a[i] = nextDouble();
        return a;
    }

}


class FastWriter extends PrintWriter {

    public FastWriter() {
        super(System.out);
    }

    public void println(boolean[] a) {
        for (int i = 0; i < a.length; i++) {
            print(a[i]);
            if (i + 1 < a.length) print(' '); else println();
        }
    }

    public void println(double[] a) {
